import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.BvnCBqQl.js";const p=JSON.parse('{"title":"附录 C 横向对比：Dify / LangGraph / n8n / Coze","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/c-comparison.md","filePath":"appendix/c-comparison.md","lastUpdated":1791442702000}'),o={name:"appendix/c-comparison.md"};function n(i,t,h,s,l,c){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="附录-c-横向对比-dify-langgraph-n8n-coze" tabindex="-1">附录 C 横向对比：Dify / LangGraph / n8n / Coze <a class="header-anchor" href="#附录-c-横向对比-dify-langgraph-n8n-coze" aria-label="Permalink to &quot;附录 C 横向对比：Dify / LangGraph / n8n / Coze&quot;">​</a></h1><blockquote><p>目的：帮你把本书学到的概念放到更大的版图里。各项目都在快速迭代，以下是<strong>架构层面</strong>的比较，具体功能以各自的官方文档为准。</p></blockquote><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Dify</th><th>LangGraph</th><th>n8n</th><th>Coze（扣子）</th></tr></thead><tbody><tr><td>形态</td><td>开源 LLM 应用平台（可视化 + API）</td><td>开源<strong>代码库</strong>（Python/JS）</td><td>开源工作流自动化平台</td><td>字节跳动的 Agent 平台（也有开源的 Coze Studio）</td></tr><tr><td>主要用户</td><td>产品、业务、开发者</td><td>开发者</td><td>运营、自动化工程师</td><td>业务人员、开发者</td></tr><tr><td>编排方式</td><td>画布 DAG + 容器节点</td><td>用代码定义状态图（<strong>允许有环</strong>）</td><td>画布 DAG</td><td>画布工作流 + Bot 配置</td></tr><tr><td>LLM 原生程度</td><td>高（模型、提示词、RAG、Agent 都是一等公民）</td><td>高</td><td>中（AI 节点是众多节点中的一类）</td><td>高</td></tr></tbody></table><h2 id="引擎模型对比" tabindex="-1">引擎模型对比 <a class="header-anchor" href="#引擎模型对比" aria-label="Permalink to &quot;引擎模型对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>Dify（graphon）</th><th>LangGraph</th><th>n8n</th></tr></thead><tbody><tr><td>图</td><td>DAG（循环用容器节点实现）</td><td>有向图，可以有环；节点之间通过共享的 <strong>State</strong> 通信</td><td>DAG，数据沿着边以 items 数组的形式传递</td></tr><tr><td>数据传递</td><td><strong>共享变量池</strong> + selector</td><td><strong>共享 State</strong> + reducer（定义各节点的更新如何合并）</td><td><strong>沿边传递</strong>（上游节点的输出就是下游节点的输入）</td></tr><tr><td>分支</td><td>分支节点 + 边状态 + 跳过传播</td><td>条件边函数返回下一个节点</td><td>IF / Switch 节点</td></tr><tr><td>并行</td><td>自动（就绪即执行）</td><td>同一个 superstep 内的节点并行（Pregel / BSP 模型）</td><td>分支并行执行（取决于执行模式）</td></tr><tr><td>暂停 / 恢复</td><td>人工输入节点 + 运行时状态序列化</td><td><strong>Checkpointer</strong> 在每一步保存 State，<code>interrupt()</code> 支持人在回路，可以“时间旅行”回到任意一步</td><td>Wait 节点</td></tr><tr><td>流式</td><td>节点事件 + 回复流排序</td><td>多种 stream mode（values / updates / messages / events）</td><td>较弱</td></tr></tbody></table><p><strong>值得注意的几点</strong>：</p><ul><li>LangGraph 允许有环，所以“Agent 循环”可以直接画成图里的一个环（模型节点 ⇄ 工具节点）。Dify 则把 Agent 封装成一个节点，外层保持 DAG。这是<strong>可控性和表达力之间的不同取舍</strong>。</li><li>LangGraph 的 checkpointer 在每个 superstep 都持久化 State，所以暂停、恢复、回放天然就支持。Dify 只在需要暂停时才做序列化（第 12 章）。对应到 mini-dify：如果想让引擎支持这些能力，第 9 章的练习 2 就是第一步。</li><li>n8n 的“数据沿边传递”是传统工作流自动化的经典模型（每个节点处理一个 items 数组）。它适合 ETL 一类的场景，但“引用三步之前的结果”就比较麻烦，这也是第 8 章选择变量池的原因。</li></ul><h2 id="和本书概念的对应" tabindex="-1">和本书概念的对应 <a class="header-anchor" href="#和本书概念的对应" aria-label="Permalink to &quot;和本书概念的对应&quot;">​</a></h2><table tabindex="0"><thead><tr><th>本书概念</th><th>Dify</th><th>LangGraph</th><th>n8n</th></tr></thead><tbody><tr><td>变量池</td><td>VariablePool</td><td>State</td><td>items + <code>$node[&quot;X&quot;].json</code> 表达式</td></tr><tr><td>节点就绪规则</td><td>边状态</td><td>superstep：上一步写过的 channel 会触发订阅它的节点</td><td>上游执行完成</td></tr><tr><td>Layer</td><td>GraphEngineLayer</td><td>callbacks / checkpointer</td><td>—</td></tr><tr><td>工具</td><td>Tool + Provider</td><td><code>@tool</code> + ToolNode</td><td>各种集成节点</td></tr><tr><td>MCP</td><td>客户端 + 服务端</td><td>通过适配器（langchain-mcp-adapters）</td><td>MCP 节点</td></tr><tr><td>发布为 API</td><td>Service API</td><td>LangGraph Platform / Server</td><td>Webhook 触发器</td></tr></tbody></table><h2 id="选型建议" tabindex="-1">选型建议 <a class="header-anchor" href="#选型建议" aria-label="Permalink to &quot;选型建议&quot;">​</a></h2><ul><li>想要<strong>开箱即用的平台</strong>，给业务人员搭建 AI 应用：Dify / Coze；</li><li>想在<strong>自己的代码里</strong>构建复杂的 Agent，需要最大的灵活性：LangGraph；</li><li>主要做<strong>跨 SaaS 的自动化</strong>，AI 只是其中一环：n8n；</li><li>想<strong>理解所有这些系统</strong>：自己写一个，也就是这本书做的事。</li></ul>',12)])])}const u=d(o,[["render",n]]);export{p as __pageData,u as default};
